// DoD 0.1 — insert the staged Layer 1 amendment into the spec immediately BEFORE
// the version-posture amendment, which src/release/readme.test.ts requires to
// remain the LAST `## ` section of the document.
//
// The spec is CRLF throughout (CR == LF == 1182); the staged amendment is LF-only.
// Splicing LF text into a CRLF file is a recorded silent defect in this repository,
// so the amendment's line endings are converted to CRLF on insertion. That changes
// bytes and not text: the script proves it by comparing both sides LF-normalised.
import { readFileSync, writeFileSync } from 'node:fs';

const SPEC = 'lab/agent-deck-spec.md';
const AMEND = 'lab/docs/amendments/spec-amendment-layer1.md';
const ANCHOR = '## Amendment 2026-08-26 — Version posture';

const spec = readFileSync(SPEC, 'utf8');
const amend = readFileSync(AMEND, 'utf8');

const idx = spec.indexOf(ANCHOR);
if (idx < 0) throw new Error('anchor not found');
if (idx !== spec.lastIndexOf(ANCHOR)) throw new Error('anchor is not unique');

// Anything already between the anchor and EOF must stay the last `## ` region.
const before = spec.slice(0, idx);
const after = spec.slice(idx);

// LF -> CRLF, and guarantee a trailing terminator plus one blank line so the
// existing anchor heading keeps a blank line above it.
let amendCrlf = amend.replace(/\r\n/g, '\n').replace(/\n/g, '\r\n');
if (!amendCrlf.endsWith('\r\n')) amendCrlf += '\r\n';

const out = before + amendCrlf + '\r\n' + after;
writeFileSync(SPEC, out, 'utf8');

// ---- proofs -------------------------------------------------------------
const back = readFileSync(SPEC, 'utf8');
const cr = (back.match(/\r/g) ?? []).length;
const lf = (back.match(/\n/g) ?? []).length;

// 1. text unedited: the inserted region, LF-normalised, equals the source file.
const norm = (s) => s.replace(/\r\n/g, '\n');
const inserted = back.slice(before.length, before.length + amendCrlf.length);
const textIdentical = norm(inserted) === norm(amend).replace(/\n?$/, '\n');

// 2. the anchor is still unique and still opens the final `## ` region.
const nIdx = back.indexOf(ANCHOR);
const tail = back.slice(nIdx);

const results = {
  crEqualsLf: cr === lf,
  cr,
  lf,
  textIdenticalModuloLineEndings: textIdentical,
  anchorUnique: nIdx === back.lastIndexOf(ANCHOR),
  anchorIsLastH2Section: !tail.includes('\n## '),
  controlByte0x14: (back.match(//g) ?? []).length,
  emDashes: (back.match(/—/g) ?? []).length,
  h2Count: (back.match(/^## /gm) ?? []).length,
  bytes: Buffer.byteLength(back, 'utf8'),
};
console.log(JSON.stringify(results, null, 2));
for (const [k, v] of Object.entries(results)) {
  if (k === 'crEqualsLf' && !v) throw new Error('MIXED LINE ENDINGS');
  if (k === 'textIdenticalModuloLineEndings' && !v) throw new Error('AMENDMENT TEXT CHANGED');
  if (k === 'anchorUnique' && !v) throw new Error('ANCHOR NOT UNIQUE');
  if (k === 'anchorIsLastH2Section' && !v) throw new Error('ANCHOR NO LONGER LAST SECTION');
  if (k === 'controlByte0x14' && v !== 0) throw new Error('CONTROL BYTES PRESENT');
}
console.log('OK');

