// Gate-owner-authorised edit (2026-09-05): spec prose must never reproduce a
// `## ` heading verbatim, because src/release/readme.test.ts locates the
// version-posture section with a raw indexOf over the whole document. Cite the
// heading without its prefix.
//
// Slice-based replacement, never String.replace: a `$'` in replacement text is
// "everything after the match" and has silently duplicated whole files here.
import { readFileSync, writeFileSync } from 'node:fs';

const F = 'lab/docs/amendments/spec-amendment-layer1.md';
const FROM = '`## Amendment 2026-08-26 — Version posture`';
const TO = '`Amendment 2026-08-26 — Version posture`';

const src = readFileSync(F, 'utf8');
const i = src.indexOf(FROM);
if (i < 0) throw new Error('citation not found');
if (i !== src.lastIndexOf(FROM)) throw new Error('more than one citation; expected exactly one');

const out = src.slice(0, i) + TO + src.slice(i + FROM.length);
writeFileSync(F, out, 'utf8');

const back = readFileSync(F, 'utf8');
console.log(
  JSON.stringify(
    {
      verbatimHeadingsRemaining: (back.match(/## Amendment 2026-08-26 — Version posture/g) ?? [])
        .length,
      citationsPresent: (back.match(/`Amendment 2026-08-26 — Version posture`/g) ?? []).length,
      bytesBefore: Buffer.byteLength(src, 'utf8'),
      bytesAfter: Buffer.byteLength(back, 'utf8'),
      delta: Buffer.byteLength(back, 'utf8') - Buffer.byteLength(src, 'utf8'),
      crLeft: (back.match(/\r/g) ?? []).length,
      emDashes: (back.match(/—/g) ?? []).length,
    },
    null,
    2,
  ),
);
console.log(back.split('\n')[3]);

