// DoD 0.2 — the staged v0.7.0 plan becomes lab/PLAN.md.
//
// It is LF-only; every other document at the lab root (the outgoing PLAN.md at
// 982/982, docs/PLAN-v0.5.0.md at 1685/1685, agent-deck-spec.md) is CRLF. A
// scripted patch that reads a source file preserving newlines and matches on
// \n-joined text finds nothing, which is a recorded trap here, so the incoming
// file is normalised to the host convention. Text is unchanged and this proves it.
import { readFileSync, writeFileSync, rmSync, existsSync } from 'node:fs';

const SRC = 'lab/docs/amendments/PLAN.md';
const DST = 'lab/PLAN.md';
const DEAD = 'lab/docs/amendments/spec-amendment-layer1.md';

if (existsSync(DST)) throw new Error('lab/PLAN.md still present — git mv it to the archive first');

const src = readFileSync(SRC, 'utf8');
const crlf = src.replace(/\r\n/g, '\n').replace(/\n/g, '\r\n');
writeFileSync(DST, crlf, 'utf8');

const back = readFileSync(DST, 'utf8');
const norm = (s) => s.replace(/\r\n/g, '\n');
if (norm(back) !== norm(src)) throw new Error('TEXT CHANGED during normalisation');

const cr = (back.match(/\r/g) ?? []).length;
const lf = (back.match(/\n/g) ?? []).length;
if (cr !== lf) throw new Error('MIXED LINE ENDINGS');

// Built from a char code rather than written as a literal: a raw control byte in
// source makes the file binary to git, and the escape for it has now been eaten
// twice by a shell on the way in. No regex literal, nothing for a shell to mangle.
const CONTROL_BYTES = [...back].filter((ch) => {
  const c = ch.charCodeAt(0);
  return c < 0x09 || (c > 0x0d && c < 0x20);
}).length;
if (CONTROL_BYTES !== 0) throw new Error(`CONTROL BYTES: ${CONTROL_BYTES}`);

// The staged sources have served their purpose: the plan is now PLAN.md and the
// spec amendment now lives inside agent-deck-spec.md.
rmSync(SRC);
rmSync(DEAD);

console.log(
  JSON.stringify(
    {
      newPlanBytes: Buffer.byteLength(back, 'utf8'),
      cr,
      lf,
      textIdenticalModuloLineEndings: true,
      controlBytes: CONTROL_BYTES,
      emDashes: (back.match(/—/g) ?? []).length,
      firstLine: back.split('\r\n')[0],
      stagedSourcesRemoved: !existsSync(SRC) && !existsSync(DEAD),
    },
    null,
    2,
  ),
);

