    // paths. Both halves, so a key called `path` holding an enum is not
    // mistaken for one, and a key holding paths under an unexpected name is
    // still visible in the full key list below it.
    let fileArgKey = null;
    for (const [k, e] of t.keys) {
      if (FILE_KEY_NAME.test(k) && e.pathLikeValues > 0) {
        if (fileArgKey === null || e.seen > t.keys.get(fileArgKey).seen) fileArgKey = k;
      }
    }
    const unexpected = [...t.keys.entries()]
      .filter(([k, e]) => !FILE_KEY_NAME.test(k) && e.stringValues > 0 && e.pathLikeValues === e.stringValues && e.stringValues > 1)
      .map(([k]) => k);
    return {
      engine: t.engine,
      toolName: t.toolName,
      calls: t.calls,
      corpora: Object.fromEntries([...t.byCorpus].sort()),
      inputShape: t.inputShape,
      fileArgKey,
      fileArgEvidence: fileArgKey === null ? null : { ...t.keys.get(fileArgKey) },
