    .filter((r) => !inAnchor.has(`${r.engine}:${r.toolName}`))
    .map((r) => `${r.engine}:${r.toolName}`)
    .sort();

  const report = { generatedFrom: 'spike/stats/toolclass-census.mjs', anchors, corpora, rows, outsideOnly };

  if (process.argv.includes('--stdout')) {
    console.log(JSON.stringify(report, null, 2));
    return;
  }
  mkdirSync(OUT_DIR, { recursive: true });
