}

function renderMarkdown(report) {
  const L = [];
  L.push('# TOOLCLASS — tool-class census, every committed corpus');
  L.push('');
  L.push('Phase 0, DoD 0.3. Generated by `spike/stats/toolclass-census.mjs`; do not hand-edit.');
  L.push('Phase 1 generates `src/stats/toolclass.ts` from this table (DoD 1.3).');
  L.push('');
  L.push('**Anchors, re-measured from the fingerprint modules rather than written down:** ' +
    Object.entries(report.anchors).map(([k, v]) => `\`${k}\` = \`${v}\``).join(', ') + '.');
  L.push('');
  L.push('**`input` column.** Three distinct states, not two. `object` is a structured input a file');
  L.push('argument can live in. `string` is an unstructured input that can carry no key at all —');
  L.push("Codex's `exec` is a `custom_tool_call` whose input is a string of JavaScript. `none` is a");
  L.push('call with no input recorded. A tool with `string` input has no file argument **by shape**,');
  L.push('which is a different fact from a tool that has an object input with no path in it.');
  L.push('');
