/**
 * Phase 0, DoD 0.3 — tool-class census across every committed corpus.
 *
 * THROWAWAY SPIKE CODE. It is frozen at the phase close and never imported by
 * `src/`. It imports only `node:` builtins, deliberately: the census is
 * evidence about the corpora, and evidence produced by the code under test is
 * not evidence. `scripts/opencode-golden.mjs` is the precedent.
 *
 * WHAT IT ANSWERS. For every distinct tool name in every corpus: which engine
 * wrote it, how many times it was called, whether the call carries a
 * STRUCTURED input object at all, and which key of that object holds a
 * filesystem path. Phase 1 generates `src/stats/toolclass.ts` from this table
 * rather than from memory.
 *
 * WHY "structured" is its own column and not an implementation detail. Codex's
 * `exec` is a `custom_tool_call` whose `input` is a STRING of JavaScript, not
 * an object. A census that assumed every tool call has an input object would
 * report `exec` as "no file argument" and be right by accident, for the wrong
 * reason, and would break the moment a string-input tool did name a file. The
 * three states are distinct and all three are reported: no input, string
 * input, object input.
 *
 * Usage:
 *   node spike/stats/toolclass-census.mjs            # writes the report
 *   node spike/stats/toolclass-census.mjs --stdout   # prints instead
 */
import { readFileSync, readdirSync, existsSync, writeFileSync, mkdirSync, statSync } from 'node:fs';
import { join, basename } from 'node:path';
import { DatabaseSync } from 'node:sqlite';

const FIXTURES = 'fixtures';
const OUT_DIR = 'docs/evidence/phase-0-stats';

/**
 * The three provenance anchors, re-measured from the fingerprint modules
 * rather than written down here. A corpus name is not an anchor because it
 * looks like one; it is an anchor because a fingerprint pins it.
 */
function readAnchors() {
  const read = (path, symbol) => {
    const src = readFileSync(path, 'utf8');
    const m = src.match(new RegExp(`${symbol}\\s*=\\s*'([^']+)'`));
    if (!m) throw new Error(`could not re-measure ${symbol} from ${path}`);
    return m[1];
  };
  return {
    cc: `cc-${read('src/parser/fingerprint.ts', 'PINNED_CC_VERSION')}`,
    opencode: `opencode-${read('src/opencode/fingerprint.ts', 'PINNED_OPENCODE_VERSION')}`,
    codex: `codex-${read('src/codex/fingerprint.ts', 'PINNED_CODEX_VERSION')}`,
  };
}

const walk = (dir) =>
  readdirSync(dir, { withFileTypes: true }).flatMap((e) =>
    e.isDirectory() ? walk(join(dir, e.name)) : [join(dir, e.name)],
  );

/**
 * Which engine wrote a corpus, decided by STRUCTURE rather than by the
 * directory's name. A corpus directory is not identified by its name — this
 * repository has a recorded case of a capture directory whose name outlived
 * its contents.
 */
function classifyCorpus(dir) {
  if (existsSync(join(dir, 'opencode.db'))) return 'opencode';
  if (existsSync(join(dir, 'projects'))) return 'cc';
  const jsonl = walk(dir).filter((p) => p.endsWith('.jsonl') && !p.includes('hook-stream'));
  for (const p of jsonl.slice(0, 4)) {
    const head = readFileSync(p, 'utf8').split('\n', 1)[0] ?? '';
    if (head.includes('"payload"')) return 'codex';
  }
  return null;
}

/** A key whose NAME claims to hold a path. Confirmed against values below. */
const FILE_KEY_NAME = /^(file_?path|notebook_?path|path|filename|file|target_?file)$/i;
/** A value that looks like a filesystem path: a separator, or a dotted basename. */
const PATH_VALUE = /[\\/]|^[\w.-]+\.[A-Za-z0-9]{1,8}$/;

/** One accumulator per (engine, toolName). */
function makeTools() {
  const tools = new Map();
  return {
    tools,
    /** `input` is `undefined` (none), a string (unstructured), or an object. */
    record(engine, corpus, toolName, input) {
      const key = `${engine}�${toolName}`;
      let t = tools.get(key);
      if (t === undefined) {
        t = {
          engine,
          toolName,
          calls: 0,
          byCorpus: new Map(),
          inputShape: { none: 0, string: 0, object: 0 },
          keys: new Map(), // key -> { seen, stringValues, pathLikeValues, sample }
        };
        tools.set(key, t);
      }
      t.calls += 1;
      t.byCorpus.set(corpus, (t.byCorpus.get(corpus) ?? 0) + 1);

      if (input === undefined || input === null) {
        t.inputShape.none += 1;
        return;
      }
      if (typeof input === 'string') {
        t.inputShape.string += 1;
        return;
      }
      if (typeof input !== 'object' || Array.isArray(input)) {
        t.inputShape.string += 1;
        return;
      }
      t.inputShape.object += 1;
      for (const [k, v] of Object.entries(input)) {
        let e = t.keys.get(k);
        if (e === undefined) {
          e = { seen: 0, stringValues: 0, pathLikeValues: 0, sample: null };
          t.keys.set(k, e);
        }
        e.seen += 1;
        if (typeof v === 'string') {
          e.stringValues += 1;
          if (PATH_VALUE.test(v)) {
            e.pathLikeValues += 1;
            if (e.sample === null) e.sample = v.length > 60 ? `${v.slice(0, 57)}...` : v;
          }
        }
      }
    },
  };
}

// ---------------------------------------------------------------------------
// Per-engine readers. Each reads raw bytes; none imports the engine it reads.
// ---------------------------------------------------------------------------

function readCc(dir, corpus, sink) {
  for (const p of walk(dir).filter((f) => f.endsWith('.jsonl'))) {
    for (const line of readFileSync(p, 'utf8').split('\n')) {
      if (line.trim() === '') continue;
      let o;
      try {
        o = JSON.parse(line);
      } catch {
        continue; // G3: malformed input is skipped, never thrown on.
      }
      const content = o?.message?.content;
      if (!Array.isArray(content)) continue;
      for (const b of content) {
        if (b && b.type === 'tool_use' && typeof b.name === 'string') {
          sink.record('cc', corpus, b.name, b.input);
        }
      }
    }
  }
}

function readCodex(dir, corpus, sink) {
  for (const p of walk(dir).filter((f) => f.endsWith('.jsonl') && !f.includes('hook-stream'))) {
    for (const line of readFileSync(p, 'utf8').split('\n')) {
      if (line.trim() === '') continue;
      let o;
      try {
        o = JSON.parse(line);
      } catch {
        continue;
      }
      const pl = o?.payload;
      if (!pl || typeof pl !== 'object') continue;

      // `function_call`  -> name + `arguments`, a JSON STRING of an object.
      // `custom_tool_call` -> name + `input`, a free STRING (JavaScript).
      // `local_shell_call` -> no name; the action object carries the command.
      if (pl.type === 'function_call' && typeof pl.name === 'string') {
        let args;
        try {
          args = JSON.parse(pl.arguments ?? '{}');
        } catch {
          args = String(pl.arguments ?? '');
        }
        sink.record('codex', corpus, pl.name, args);
      } else if (pl.type === 'custom_tool_call' && typeof pl.name === 'string') {
        sink.record('codex', corpus, pl.name, typeof pl.input === 'string' ? pl.input : pl.input);
      } else if (pl.type === 'local_shell_call') {
        sink.record('codex', corpus, 'local_shell_call', pl.action);
      }
    }
  }
}

function readOpenCode(dir, corpus, sink) {
  // Read-only, and journal-mode `delete` on the committed corpora. `immutable=1`
  // is REFUSED by the production accessor on any WAL file and is not used here
  // either: it skips the WAL and returns a confidently stale tree.
  const db = new DatabaseSync(join(dir, 'opencode.db'), { readOnly: true });
  try {
    for (const row of db.prepare('SELECT data FROM part').all()) {
      let d;
      try {
        d = JSON.parse(row.data);
      } catch {
        continue;
      }
      if (d?.type !== 'tool') continue;
      const name = typeof d.tool === 'string' ? d.tool : null;
      if (name === null) continue;
      sink.record('opencode', corpus, name, d?.state?.input);
    }
  } finally {
    db.close();
  }
}

// ---------------------------------------------------------------------------

function main() {
  const anchors = readAnchors();
  const anchorSet = new Set(Object.values(anchors));
