      inputShape: t.inputShape,
      fileArgKey,
      fileArgEvidence: fileArgKey === null ? null : { ...t.keys.get(fileArgKey) },
      allKeys: Object.fromEntries([...t.keys].sort().map(([k, e]) => [k, e.seen])),
      pathLikeUnderUnexpectedKey: unexpected,
