/**
 * Tool class, which `src/stats/toolclass.ts` needs and a bare key census does
 * not supply. Spec §E: `filePath` is "the structured file argument of
 * FILE-CLASS tools", so membership of that class is part of the table.
 *
 * SEARCH IS NOT FILE-CLASS, AND THAT IS THE ONE THAT MATTERS. `Grep` and
 * `glob` both expose a `path` key whose values are genuinely path-shaped, so
 * the value test alone promotes them — and their `path` is the DIRECTORY the
 * search ran over, not a file the session touched. F1 counts touches per file;
 * admitting a search scope would report one "touch" of a directory for every
 * grep, inflating the busiest rows in the table with something the user never
 * edited. They are classed `search`, keep their key in the audit table below,
 * and get no `filePath`.
 *
 * Names are matched per engine and case-sensitively, because the three engines
 * genuinely differ (`Read` vs `read`) and a case-insensitive match would hide
 * a new tool arriving under a near-miss name.
 */
const CLASS_BY_NAME = new Map(
  Object.entries({
    // Claude Code
    Read: 'read', Write: 'write', Edit: 'edit', NotebookEdit: 'edit',
    Glob: 'search', Grep: 'search', Bash: 'shell', Agent: 'spawn',
    // OpenCode
    read: 'read', write: 'write', edit: 'edit', patch: 'edit',
