// path JSON-escaped (`C:\\Users\\...`), tools and prose hold it with forward
// slashes, and the MSYS shell form (`/c/Users/...`) appears in captured command
// output. Missing one spelling leaves identity in the corpus and the sweep is
// what would find it — after the bytes were already committed.
import { readFileSync, writeFileSync, mkdirSync, cpSync, readdirSync, statSync, renameSync } from 'node:fs';
import { join } from 'node:path';
import os from 'node:os';

