const LIVE_SLUG = 'c--Users-dev-projects-agent-deck';
const DEST_SLUG = 'c--Users-dev-projects-agent-deck';
const CORPUS = 'fixtures/cc-2.1.260';
const DEST = join(CORPUS, 'projects', DEST_SLUG);

const home = os.homedir();
const liveProjects = join(home, '.claude', 'projects', LIVE_SLUG);

// ---- 1. copy -------------------------------------------------------------
mkdirSync(DEST, { recursive: true });
cpSync(join(liveProjects, `${SESSION}.jsonl`), join(DEST, `${SESSION}.jsonl`));
cpSync(join(liveProjects, SESSION), join(DEST, SESSION), { recursive: true });

// ---- 2. repo-path + slug rewrite ----------------------------------------
// Ordered longest-first so a longer form is never left half-rewritten by a
// shorter one that is its prefix.
const REPO_WIN = 'C:\\Users\\dev\\Documents\\projects\\agent-deck';
const REPO_FWD = 'C:/Users/dev/projects/agent-deck';
const REPO_MSYS = '/c/Users/dev/projects/agent-deck';
const HOME_WIN = 'C:\\Users\\dev';
const HOME_FWD = 'C:/Users/dev';
const HOME_MSYS = '/c/Users/dev';

const DEV_WIN = 'C:\\Users\\dev\\projects\\agent-deck';
const DEV_FWD = 'C:/Users/dev/projects/agent-deck';
const DEV_MSYS = '/c/Users/dev/projects/agent-deck';
