const DEVHOME_FWD = 'C:/Users/dev';
const DEVHOME_MSYS = '/c/Users/dev';

/** JSON-escaped spelling of a Windows path, as it appears inside a .jsonl. */
const esc = (p) => p.replace(/\\/g, '\\\\');

