  [esc(REPO_WIN), esc(DEV_WIN)],
  [REPO_WIN, DEV_WIN],
  [REPO_FWD, DEV_FWD],
  [REPO_MSYS, DEV_MSYS],
  [LIVE_SLUG, DEST_SLUG],
