/**
 * Phase 0, DoD 0.4 and 0.6 — derive F1..F12 for every corpus session, from
 * parsed STRUCTURE only, and measure the two constants.
 *
 * THROWAWAY SPIKE CODE, frozen at the phase close, never imported by `src/`.
 * `node:` builtins only — the same rule `scripts/opencode-golden.mjs` follows,
 * and for the same reason: a fact derived by the engine under test is not
 * evidence that the fact is derivable.
 *
 * THE STRUCTURE-ONLY RULE, AND WHERE IT BITES. DoD 0.4 forbids a regex over
 * message or payload TEXT. Every value read here is a named field or a key of a
 * structured input object. The one place that rule decides an outcome rather
 * than merely constraining style is Codex tool status: a Codex tool result is an
 * array of free text with no error field anywhere, and the call item's own
 * `status` is present on 10 of 41 calls and always reads `completed`. So "did
 * this call fail" is answerable for Claude Code (`is_error`) and OpenCode
 * (`state.status`) and is NOT answerable for Codex without reading the text.
 * That makes F4 and the error halves of F1/F2 `UNAVAILABLE:codex` — by shape,
 * not by omission, and the report says which.
 *
 * Usage:
 *   node lab/spike/stats/derive-facts.mjs           # writes the report
 *   node lab/spike/stats/derive-facts.mjs --stdout  # prints the summary only
 */
import { readFileSync, readdirSync, existsSync, writeFileSync, mkdirSync, statSync } from 'node:fs';
import { join } from 'node:path';
import { createHash } from 'node:crypto';
import { DatabaseSync } from 'node:sqlite';

const FIXTURES = 'fixtures';
const OUT_DIR = 'docs/evidence/phase-0-stats';

/** Default from the spec; 0.6 confirms or moves it from the histogram. */
const LOOP_MIN_DEFAULT = 3;

// ---------------------------------------------------------------------------
// Shared helpers
// ---------------------------------------------------------------------------

const walk = (dir) =>
  readdirSync(dir, { withFileTypes: true }).flatMap((e) =>
    e.isDirectory() ? walk(join(dir, e.name)) : [join(dir, e.name)],
  );

/**
 * Canonical JSON: keys sorted at every depth, so two inputs that differ only in
 * key order hash the same. Arrays keep their order — order is meaning there.
 */
function canonical(value) {
  if (value === null || typeof value !== 'object') return JSON.stringify(value) ?? 'null';
  if (Array.isArray(value)) return `[${value.map(canonical).join(',')}]`;
  const keys = Object.keys(value).sort();
  return `{${keys.map((k) => `${JSON.stringify(k)}:${canonical(value[k])}`).join(',')}}`;
}

const inputHash = (input) => createHash('sha256').update(canonical(input), 'utf8').digest('hex');

function readAnchors() {
  const read = (path, symbol) => {
    const m = readFileSync(path, 'utf8').match(new RegExp(`${symbol}\\s*=\\s*'([^']+)'`));
    if (!m) throw new Error(`could not re-measure ${symbol}`);
    return m[1];
  };
  return {
    cc: `cc-${read('src/parser/fingerprint.ts', 'PINNED_CC_VERSION')}`,
    opencode: `opencode-${read('src/opencode/fingerprint.ts', 'PINNED_OPENCODE_VERSION')}`,
    codex: `codex-${read('src/codex/fingerprint.ts', 'PINNED_CODEX_VERSION')}`,
  };
}

/** The census's classes, re-derived here so the two agree by construction. */
const CLASS_BY_NAME = new Map(
  Object.entries({
    Read: 'read', Write: 'write', Edit: 'edit', NotebookEdit: 'edit',
    Glob: 'search', Grep: 'search', Bash: 'shell', Agent: 'spawn',
    read: 'read', write: 'write', edit: 'edit', patch: 'edit',
    glob: 'search', grep: 'search', bash: 'shell', task: 'spawn',
    exec: 'shell', exec_command: 'shell', local_shell_call: 'shell',
    spawn_agent: 'spawn', wait_agent: 'spawn', send_message: 'spawn',
    send_input: 'spawn', list_agents: 'spawn',
  }),
);
const FILE_CLASSES = new Set(['read', 'write', 'edit']);
const FILE_KEY = new Map(
  Object.entries({ Read: 'file_path', Write: 'file_path', Edit: 'file_path', NotebookEdit: 'notebook_path', read: 'filePath', write: 'filePath', edit: 'filePath', patch: 'filePath' }),
);

const classOf = (name) => CLASS_BY_NAME.get(name) ?? 'other';
function filePathOf(name, input) {
  if (!FILE_CLASSES.has(classOf(name))) return undefined;
  const key = FILE_KEY.get(name);
  if (key === undefined || input === null || typeof input !== 'object') return undefined;
  const v = input[key];
  return typeof v === 'string' && v !== '' ? v : undefined;
}

const num = (v) => (typeof v === 'number' && Number.isFinite(v) ? v : 0);

// ---------------------------------------------------------------------------
// Engine readers -> the normalised shape the facts are computed from
//
//   session = { corpus, engine, sessionId, schemaOk, parked[], model?,
//               windowTokens?, costUsd?, costSource?, compactions[],
//               agents: [{ agentId, kind, tools[], usageSeries[] }] }
//   tool    = { ordinal, toolName, toolClass, filePath?, inputHash,
//               status: 'done'|'error'|'running'|'unknown', durationMs? }
//   turn    = { ordinal, input, cacheCreation, cacheRead, output }
// ---------------------------------------------------------------------------

function readCcCorpus(dir, corpus) {
  const sessions = [];
  const projects = join(dir, 'projects');
  if (!existsSync(projects)) return sessions;
  for (const slug of readdirSync(projects)) {
    const slugDir = join(projects, slug);
    if (!statSync(slugDir).isDirectory()) continue;
    for (const entry of readdirSync(slugDir)) {
      if (!entry.endsWith('.jsonl')) continue;
      const sessionId = entry.slice(0, -6);
      const files = [{ agentId: 'root', kind: 'main', path: join(slugDir, entry) }];
      const subDir = join(slugDir, sessionId, 'subagents');
      if (existsSync(subDir)) {
        for (const f of readdirSync(subDir)) {
          if (f.endsWith('.jsonl')) files.push({ agentId: f.slice('agent-'.length, -6), kind: 'subagent', path: join(subDir, f) });
        }
      }
      sessions.push(readCcSession(corpus, sessionId, files));
    }
  }
  return sessions;
}

function readCcSession(corpus, sessionId, files) {
  const agents = [];
  const compactions = [];
  let model;
  let malformed = 0;

  for (const f of files) {
    const tools = [];
    const usageById = new Map();
    const errorByToolUseId = new Map();
    let ordinal = 0;

    for (const line of readFileSync(f.path, 'utf8').split('\n')) {
      if (line.trim() === '') continue;
      let o;
      try {
        o = JSON.parse(line);
      } catch {
        malformed += 1;
        continue;
      }
      if (f.kind === 'main' && o.compactMetadata && typeof o.compactMetadata === 'object') {
        compactions.push({
          ordinal: tools.length,
          trigger: typeof o.compactMetadata.trigger === 'string' ? o.compactMetadata.trigger : 'unknown',
          promptBefore: num(o.compactMetadata.preTokens) || undefined,
          promptAfter: num(o.compactMetadata.postTokens) || undefined,
        });
      }
      const msg = o.message;
      if (!msg || typeof msg !== 'object') continue;
      if (typeof msg.model === 'string' && model === undefined) model = msg.model;

      // Usage, de-duplicated by message id: CC repeats the SAME usage object on
      // every content-block line of one streamed message, growing as it goes.
      // Keep the maximum per id and sum across distinct ids — the production
      // rule in `src/model/graft.ts`, restated rather than imported.
      if (typeof msg.id === 'string' && msg.usage && typeof msg.usage === 'object') {
        const u = msg.usage;
        const turn = {
          input: num(u.input_tokens),
          cacheCreation: num(u.cache_creation_input_tokens),
          cacheRead: num(u.cache_read_input_tokens),
          output: num(u.output_tokens),
        };
        const prev = usageById.get(msg.id);
        usageById.set(msg.id, prev === undefined ? { ...turn, ordinal: usageById.size } : {
          ordinal: prev.ordinal,
          input: Math.max(prev.input, turn.input),
          cacheCreation: Math.max(prev.cacheCreation, turn.cacheCreation),
          cacheRead: Math.max(prev.cacheRead, turn.cacheRead),
          output: Math.max(prev.output, turn.output),
        });
      }

      const content = msg.content;
      if (!Array.isArray(content)) continue;
      for (const b of content) {
        if (!b || typeof b !== 'object') continue;
        if (b.type === 'tool_use' && typeof b.name === 'string') {
          tools.push({
            id: typeof b.id === 'string' ? b.id : `#${String(ordinal)}`,
            ordinal: ordinal++,
            toolName: b.name,
            toolClass: classOf(b.name),
            filePath: filePathOf(b.name, b.input),
            inputHash: inputHash(b.input ?? null),
            status: 'done',
          });
        } else if (b.type === 'tool_result' && typeof b.tool_use_id === 'string') {
          errorByToolUseId.set(b.tool_use_id, b.is_error === true);
        }
      }
    }
    for (const t of tools) {
      const e = errorByToolUseId.get(t.id);
      t.status = e === true ? 'error' : e === false ? 'done' : 'unknown';
    }
    agents.push({
      agentId: f.agentId,
      kind: f.kind,
      tools,
      usageSeries: [...usageById.values()].sort((a, b) => a.ordinal - b.ordinal),
    });
  }

  return { corpus, engine: 'cc', sessionId, schemaOk: true, parked: [], model, compactions, agents, malformed };
}

function readOpenCodeCorpus(dir, corpus) {
  const db = new DatabaseSync(join(dir, 'opencode.db'), { readOnly: true });
  const sessions = [];
  try {
    const rows = db.prepare('SELECT id, parent_id, model, cost, time_created FROM session').all();
    const parts = db.prepare('SELECT id, session_id, message_id, data FROM part ORDER BY id').all();
    const bySession = new Map();
    for (const p of parts) {
      if (!bySession.has(p.session_id)) bySession.set(p.session_id, []);
      bySession.get(p.session_id).push(p);
    }
    // One SessionState per ROOT session; children become subagents.
    const children = new Map();
    for (const r of rows) {
      if (r.parent_id) {
        if (!children.has(r.parent_id)) children.set(r.parent_id, []);
        children.get(r.parent_id).push(r);
      }
    }
    for (const root of rows.filter((r) => !r.parent_id)) {
      const agents = [];
      const compactions = [];
      let cost = num(root.cost);
      const build = (row, kind) => {
        const tools = [];
        const usageSeries = [];
        let ordinal = 0;
        for (const p of bySession.get(row.id) ?? []) {
          let d;
          try {
            d = JSON.parse(p.data);
          } catch {
            continue;
          }
          if (d.type === 'tool' && typeof d.tool === 'string') {
            const st = d?.state?.status;
            const time = d?.state?.time;
            tools.push({
              id: typeof d.callID === 'string' ? d.callID : p.id,
              ordinal: ordinal++,
              toolName: d.tool,
              toolClass: classOf(d.tool),
              filePath: filePathOf(d.tool, d?.state?.input),
              inputHash: inputHash(d?.state?.input ?? null),
              status: st === 'error' ? 'error' : st === 'completed' ? 'done' : st === 'running' ? 'running' : 'unknown',
              durationMs: time && num(time.end) > 0 && num(time.start) > 0 ? num(time.end) - num(time.start) : undefined,
            });
          } else if (d.type === 'step-finish') {
            const t = d.tokens ?? {};
            usageSeries.push({
              ordinal: usageSeries.length,
              input: num(t.input),
              cacheCreation: num(t?.cache?.write),
              cacheRead: num(t?.cache?.read),
              output: num(t.output),
            });
            cost += num(d.cost);
          } else if (d.type === 'compaction') {
            compactions.push({ ordinal: tools.length, trigger: 'engine', promptBefore: undefined, promptAfter: undefined });
          }
        }
        agents.push({ agentId: row.id, kind, tools, usageSeries });
      };
      build(root, 'main');
      for (const c of children.get(root.id) ?? []) build(c, 'subagent');
      sessions.push({
        corpus, engine: 'opencode', sessionId: root.id, schemaOk: true, parked: [],
        model: typeof root.model === 'string' ? root.model : undefined,
        costUsd: num(root.cost) > 0 ? num(root.cost) : undefined,
        costSource: num(root.cost) > 0 ? 'engine' : undefined,
        compactions, agents, malformed: 0,
      });
    }
  } finally {
    db.close();
  }
  return sessions;
}

function readCodexCorpus(dir, corpus) {
  // One rollout file per THREAD. A thread's own file is its agent; the root is
  // the thread with no parent. Grouping is by directory (one run per capture).
  const byRun = new Map();
  for (const p of walk(dir).filter((f) => f.endsWith('.jsonl') && !f.includes('hook-stream'))) {
    const run = p.split(/[\\/]/).slice(0, 3).join('/');
    if (!byRun.has(run)) byRun.set(run, []);
    byRun.get(run).push(p);
  }
  const sessions = [];
  for (const [run, files] of byRun) {
    const agents = [];
    let windowTokens;
    let model;
    let sessionId = run;
    for (const p of files) {
      const tools = [];
      const usageSeries = [];
      let ordinal = 0;
      let threadId;
      let kind = 'subagent';
      for (const line of readFileSync(p, 'utf8').split('\n')) {
        if (line.trim() === '') continue;
        let o;
        try {
          o = JSON.parse(line);
        } catch {
          continue;
        }
        const pl = o.payload;
        if (!pl || typeof pl !== 'object') continue;
        if (o.type === 'session_meta' || pl.type === 'session_meta' || pl.id !== undefined && pl.cwd !== undefined) {
          if (typeof pl.id === 'string' && threadId === undefined) threadId = pl.id;
          const src = pl.source;
          if (src === undefined || src === null) kind = 'main';
        }
        if (pl.type === 'task_started') {
          const w = num(pl.model_context_window);
          if (w > 0) windowTokens = w;
        }
        if (pl.type === 'turn_context' && typeof pl.model === 'string' && model === undefined) model = pl.model;
        if (pl.model !== undefined && typeof pl.model === 'string' && model === undefined) model = pl.model;
        if (pl.type === 'token_count' && pl.info && typeof pl.info === 'object') {
          const last = pl.info.last_token_usage;
          const w = num(pl.info.model_context_window);
          if (w > 0) windowTokens = w;
          if (last && typeof last === 'object') {
            usageSeries.push({
              ordinal: usageSeries.length,
              // `input_tokens` here is the TOTAL sent; `cached_input_tokens` is
              // the cached part of it. Reported separately so the reader is not
              // asked to trust an arithmetic we did not measure.
              input: num(last.input_tokens) - num(last.cached_input_tokens),
              cacheCreation: num(last.cache_write_input_tokens),
              cacheRead: num(last.cached_input_tokens),
              output: num(last.output_tokens),
            });
          }
        }
        const isCall = pl.type === 'function_call' || pl.type === 'custom_tool_call' || pl.type === 'local_shell_call';
        if (isCall) {
          const name = typeof pl.name === 'string' ? pl.name : 'local_shell_call';
          let input = null;
          if (pl.type === 'function_call') {
            try {
              input = JSON.parse(pl.arguments ?? '{}');
            } catch {
              input = String(pl.arguments ?? '');
            }
          } else if (pl.type === 'custom_tool_call') input = typeof pl.input === 'string' ? pl.input : (pl.input ?? null);
          else input = pl.action ?? null;
          tools.push({
            id: typeof pl.call_id === 'string' ? pl.call_id : `#${String(ordinal)}`,
            ordinal: ordinal++,
            toolName: name,
            toolClass: classOf(name),
            filePath: filePathOf(name, input),
            inputHash: inputHash(input),
            // No structural error signal exists. `unknown`, never `done`: a
            // default of `done` would report a zero error count as a fact.
            status: 'unknown',
          });
        }
      }
      agents.push({ agentId: threadId ?? p, kind, tools, usageSeries });
    }
    if (agents.length > 0 && !agents.some((a) => a.kind === 'main')) agents[0].kind = 'main';
    sessions.push({ corpus, engine: 'codex', sessionId, schemaOk: true, parked: [], model, windowTokens, compactions: [], agents, malformed: 0 });
  }
  return sessions;
}

// ---------------------------------------------------------------------------
// Facts
// ---------------------------------------------------------------------------

function deriveFacts(session, loopMin, spikeTokens) {
  const allTools = session.agents.flatMap((a) => a.tools);
  const statusKnown = allTools.some((t) => t.status === 'done' || t.status === 'error');

  // F1 — per-file counts and first/last touch ordinal.
  const files = new Map();
  for (const a of session.agents) {
    for (const t of a.tools) {
      if (t.filePath === undefined) continue;
      let f = files.get(t.filePath);
      if (f === undefined) {
        f = { path: t.filePath, read: 0, edit: 0, write: 0, error: 0, first: t.ordinal, last: t.ordinal };
        files.set(t.filePath, f);
      }
      if (t.toolClass === 'read') f.read += 1;
      else if (t.toolClass === 'edit') f.edit += 1;
      else if (t.toolClass === 'write') f.write += 1;
      if (t.status === 'error') f.error += 1;
      f.first = Math.min(f.first, t.ordinal);
      f.last = Math.max(f.last, t.ordinal);
    }
  }

  // F2 — per tool.
  const tools = new Map();
  for (const t of allTools) {
    let e = tools.get(t.toolName);
    if (e === undefined) {
      e = { toolName: t.toolName, calls: 0, errors: 0, durationSum: 0, durationMax: 0 };
      tools.set(t.toolName, e);
    }
    e.calls += 1;
    if (t.status === 'error') e.errors += 1;
    if (t.durationMs !== undefined) {
      e.durationSum += t.durationMs;
      e.durationMax = Math.max(e.durationMax, t.durationMs);
    }
  }

  // F3 — identical-call loops, WITHIN ONE AGENT (locked answer).
  const loops = [];
  for (const a of session.agents) {
    const seen = new Map();
    for (const t of a.tools) {
      const k = `${t.toolName}�${t.inputHash}`;
      if (!seen.has(k)) seen.set(k, []);
      seen.get(k).push(t.ordinal);
    }
    for (const [k, ordinals] of seen) {
      if (ordinals.length >= loopMin) {
        loops.push({ agentId: a.agentId, toolName: k.split('�')[0], count: ordinals.length, ordinals, readClass: classOf(k.split('�')[0]) === 'read' });
      }
    }
  }

  // F4 — churn chain: Edit/Write(X) -> any error tool -> Edit/Write(X), same agent.
  const churn = [];
  for (const a of session.agents) {
    const writes = a.tools.filter((t) => (t.toolClass === 'edit' || t.toolClass === 'write') && t.filePath !== undefined);
    for (let i = 0; i < writes.length; i += 1) {
      for (let j = i + 1; j < writes.length; j += 1) {
        if (writes[i].filePath !== writes[j].filePath) continue;
        const between = a.tools.filter((t) => t.ordinal > writes[i].ordinal && t.ordinal < writes[j].ordinal);
        if (between.some((t) => t.status === 'error')) {
          churn.push({ agentId: a.agentId, path: writes[i].filePath, from: writes[i].ordinal, to: writes[j].ordinal, ordinals: between.map((t) => t.ordinal) });
        }
        break; // the NEXT write of the same file only
      }
    }
  }

  // F5 — burn.
  const sumTurns = (turns) => turns.reduce(
    (acc, t) => ({ prompt: acc.prompt + t.input + t.cacheCreation + t.cacheRead, output: acc.output + t.output }),
    { prompt: 0, output: 0 },
  );
  const perAgentBurn = session.agents.map((a) => ({ agentId: a.agentId, ...sumTurns(a.usageSeries) }));
  const burn = perAgentBurn.reduce((acc, b) => ({ prompt: acc.prompt + b.prompt, output: acc.output + b.output }), { prompt: 0, output: 0 });
  const hasSeries = session.agents.some((a) => a.usageSeries.length > 0);

  // F6 — cache ratio per agent.
  const cacheRatios = session.agents
    .filter((a) => a.usageSeries.length > 0)
    .map((a) => {
      const s = sumTurns(a.usageSeries);
      const cacheRead = a.usageSeries.reduce((n, t) => n + t.cacheRead, 0);
      return { agentId: a.agentId, ratio: s.prompt > 0 ? cacheRead / s.prompt : null };
    })
    .filter((r) => r.ratio !== null);

  // F7 — context churn: turn-over-turn delta of cache-creation tokens.
  const contextChurn = [];
  const deltas = [];
  for (const a of session.agents) {
    for (let i = 1; i < a.usageSeries.length; i += 1) {
      const d = a.usageSeries[i].cacheCreation - a.usageSeries[i - 1].cacheCreation;
      deltas.push(d);
      if (d >= spikeTokens) contextChurn.push({ agentId: a.agentId, ordinal: a.usageSeries[i].ordinal, delta: d });
    }
  }

  // F8 — subagents.
  const subagents = session.agents.filter((a) => a.kind === 'subagent');
  const silent = subagents.filter((a) => a.tools.length === 0);
  const spawnCalls = allTools.filter((t) => t.toolClass === 'spawn');
  const spawnNotDone = spawnCalls.filter((t) => t.status !== 'done');

  // F10 — context fill.
  const lastTurn = session.agents.find((a) => a.kind === 'main')?.usageSeries.at(-1);
  const contextNowPrompt = lastTurn ? lastTurn.input + lastTurn.cacheCreation + lastTurn.cacheRead : undefined;
  const contextFill = session.windowTokens && contextNowPrompt !== undefined && session.windowTokens > 0
    ? contextNowPrompt / session.windowTokens
    : undefined;

  return {
    corpus: session.corpus, engine: session.engine, sessionId: session.sessionId,
    F1: { files: files.size, rows: [...files.values()], available: files.size > 0, errorColumnAvailable: statusKnown },
    F2: { tools: tools.size, rows: [...tools.values()], errorColumnAvailable: statusKnown, durationAvailable: allTools.some((t) => t.durationMs !== undefined) },
    F3: { loops: loops.length, rows: loops },
    F4: { chains: churn.length, rows: churn, available: statusKnown },
    F5: { burn, perAgent: perAgentBurn, available: hasSeries },
    F6: { ratios: cacheRatios, available: cacheRatios.length > 0 },
    F7: { spikes: contextChurn.length, deltas, available: deltas.length > 0 },
    F8: { subagents: subagents.length, silent: silent.length, spawnCalls: spawnCalls.length, spawnNotDone: spawnNotDone.length, available: true },
    F9: { costUsd: session.costUsd, costSource: session.costSource, available: session.costUsd !== undefined },
    F10: { windowTokens: session.windowTokens, contextFill, available: contextFill !== undefined },
    F11: { coverage: session.schemaOk && session.parked.length === 0 ? 'full' : 'excluded:parked', available: true },
    F12: { count: session.compactions.length, rows: session.compactions, available: session.compactions.length > 0 },
    _toolCount: allTools.length,
    _statusKnown: statusKnown,
  };
}

// ---------------------------------------------------------------------------

function main() {
  const anchors = readAnchors();
  const anchorSet = new Set(Object.values(anchors));
  const sessions = [];

  for (const name of readdirSync(FIXTURES).sort()) {
    const dir = join(FIXTURES, name);
    if (!statSync(dir).isDirectory()) continue;
    if (existsSync(join(dir, 'opencode.db'))) sessions.push(...readOpenCodeCorpus(dir, name));
    else if (existsSync(join(dir, 'projects'))) sessions.push(...readCcCorpus(dir, name));
    else {
      const jsonl = walk(dir).filter((p) => p.endsWith('.jsonl') && !p.includes('hook-stream'));
      const isCodex = jsonl.slice(0, 4).some((p) => (readFileSync(p, 'utf8').split('\n', 1)[0] ?? '').includes('"payload"'));
      if (isCodex) sessions.push(...readCodexCorpus(dir, name));
    }
  }

  // ---- 0.6: the two constants, from the ANCHOR corpora's histograms --------
  const anchorSessions = sessions.filter((s) => anchorSet.has(s.corpus));

  // LOOP_MIN: how many loops each candidate threshold selects.
  const repeatCounts = [];
  for (const s of anchorSessions) {
    for (const a of s.agents) {
      const seen = new Map();
      for (const t of a.tools) {
        const k = `${t.toolName}�${t.inputHash}`;
        seen.set(k, (seen.get(k) ?? 0) + 1);
      }
      for (const n of seen.values()) repeatCounts.push(n);
    }
  }
  const loopHistogram = {};
  for (const n of repeatCounts) loopHistogram[n] = (loopHistogram[n] ?? 0) + 1;
  const loopsAtThreshold = {};
  for (const th of [2, 3, 4, 5, 6]) loopsAtThreshold[th] = repeatCounts.filter((n) => n >= th).length;

  // SPIKE_TOKENS: the value at which <= 5% of real turns qualify, to the
  // nearest thousand. Both candidate quantities are reported — the per-turn
  // cache-creation figure and its turn-over-turn delta — because the spec
  // sentence names the delta and a reader who assumed the level would get a
  // different constant. The one used is named beside the number.
  const allDeltas = [];
  const allLevels = [];
  for (const s of anchorSessions) {
    for (const a of s.agents) {
      for (let i = 0; i < a.usageSeries.length; i += 1) {
        allLevels.push(a.usageSeries[i].cacheCreation);
        if (i > 0) allDeltas.push(a.usageSeries[i].cacheCreation - a.usageSeries[i - 1].cacheCreation);
      }
    }
  }
  const pick95 = (values) => {
    if (values.length === 0) return null;
    const sorted = [...values].sort((a, b) => a - b);
    const idx = Math.floor(sorted.length * 0.95);
    const raw = sorted[Math.min(idx, sorted.length - 1)];
    return { raw, rounded: Math.max(1000, Math.round(raw / 1000) * 1000), n: values.length };
  };
  const spikeFromDelta = pick95(allDeltas);
  const spikeFromLevel = pick95(allLevels);
  const SPIKE_TOKENS = spikeFromDelta?.rounded ?? 1000;
  const qualifying = allDeltas.filter((d) => d >= SPIKE_TOKENS).length;

  // ---- facts, now that the constants exist -------------------------------
  const facts = sessions.map((s) => deriveFacts(s, LOOP_MIN_DEFAULT, SPIKE_TOKENS));

  // ---- the fact x engine verdict table ------------------------------------
  const ENGINES = ['cc', 'opencode', 'codex'];
  const FACT_IDS = ['F1', 'F2', 'F3', 'F4', 'F5', 'F6', 'F7', 'F8', 'F9', 'F10', 'F11', 'F12'];
  const table = {};
  for (const id of FACT_IDS) {
    table[id] = {};
    for (const eng of ENGINES) {
      const rows = facts.filter((f) => f.engine === eng);
      const fired = rows.filter((f) => f[id].available === true).length;
      table[id][eng] = { sessions: rows.length, fired };
    }
  }

  const report = {
    generatedFrom: 'lab/spike/stats/derive-facts.mjs',
    anchors,
    constants: { LOOP_MIN: LOOP_MIN_DEFAULT, SPIKE_TOKENS, spikeFromDelta, spikeFromLevel, qualifyingTurns: qualifying, totalDeltas: allDeltas.length },
    loopHistogram, loopsAtThreshold,
    sessions: facts.length,
    table,
    facts,
  };

  mkdirSync(OUT_DIR, { recursive: true });
  writeFileSync(join(OUT_DIR, 'facts.json'), `${JSON.stringify(report, null, 1)}\n`, 'utf8');

  console.log(`sessions derived: ${facts.length}  (anchor sessions: ${anchorSessions.length})`);
  console.log(`SPIKE_TOKENS = ${String(SPIKE_TOKENS)}  from the 95th percentile of ${String(allDeltas.length)} turn-over-turn cache-creation deltas (raw ${String(spikeFromDelta?.raw)}); ${String(qualifying)}/${String(allDeltas.length)} turns qualify = ${(100 * qualifying / Math.max(1, allDeltas.length)).toFixed(1)}%`);
  console.log(`LOOP_MIN = ${String(LOOP_MIN_DEFAULT)}; loops selected at thresholds ${JSON.stringify(loopsAtThreshold)}`);
  console.log('');
  console.log('fact   cc              opencode        codex');
  for (const id of FACT_IDS) {
    const cell = (e) => `${String(table[id][e].fired)}/${String(table[id][e].sessions)}`.padEnd(16);
    console.log(`${id.padEnd(6)} ${cell('cc')}${cell('opencode')}${cell('codex')}`);
  }
}

main();

toolUseResult.content:
/**
 * Phase 0, DoD 0.4 and 0.6 — derive F1..F12 for every corpus session, from
 * parsed STRUCTURE only, and measure the two constants.
 *
 * THROWAWAY SPIKE CODE, frozen at the phase close, never imported by `src/`.
 * `node:` builtins only — the same rule `scripts/opencode-golden.mjs` follows,
 * and for the same reason: a fact derived by the engine under test is not
 * evidence that the fact is derivable.
 *
 * THE STRUCTURE-ONLY RULE, AND WHERE IT BITES. DoD 0.4 forbids a regex over
 * message or payload TEXT. Every value read here is a named field or a key of a
 * structured input object. The one place that rule decides an outcome rather
 * than merely constraining style is Codex tool status: a Codex tool result is an
 * array of free text with no error field anywhere, and the call item's own
 * `status` is present on 10 of 41 calls and always reads `completed`. So "did
 * this call fail" is answerable for Claude Code (`is_error`) and OpenCode
 * (`state.status`) and is NOT answerable for Codex without reading the text.
 * That makes F4 and the error halves of F1/F2 `UNAVAILABLE:codex` — by shape,
 * not by omission, and the report says which.
 *
 * Usage:
 *   node lab/spike/stats/derive-facts.mjs           # writes the report
 *   node lab/spike/stats/derive-facts.mjs --stdout  # prints the summary only
 */
import { readFileSync, readdirSync, existsSync, writeFileSync, mkdirSync, statSync } from 'node:fs';
import { join } from 'node:path';
import { createHash } from 'node:crypto';
import { DatabaseSync } from 'node:sqlite';

const FIXTURES = 'fixtures';
const OUT_DIR = 'docs/evidence/phase-0-stats';

/** Default from the spec; 0.6 confirms or moves it from the histogram. */
const LOOP_MIN_DEFAULT = 3;

// ---------------------------------------------------------------------------
// Shared helpers
// ---------------------------------------------------------------------------

const walk = (dir) =>
  readdirSync(dir, { withFileTypes: true }).flatMap((e) =>
    e.isDirectory() ? walk(join(dir, e.name)) : [join(dir, e.name)],
  );

/**
 * Canonical JSON: keys sorted at every depth, so two inputs that differ only in
 * key order hash the same. Arrays keep their order — order is meaning there.
 */
function canonical(value) {
  if (value === null || typeof value !== 'object') return JSON.stringify(value) ?? 'null';
  if (Array.isArray(value)) return `[${value.map(canonical).join(',')}]`;
  const keys = Object.keys(value).sort();
  return `{${keys.map((k) => `${JSON.stringify(k)}:${canonical(value[k])}`).join(',')}}`;
}

const inputHash = (input) => createHash('sha256').update(canonical(input), 'utf8').digest('hex');

function readAnchors() {
  const read = (path, symbol) => {
    const m = readFileSync(path, 'utf8').match(new RegExp(`${symbol}\\s*=\\s*'([^']+)'`));
    if (!m) throw new Error(`could not re-measure ${symbol}`);
    return m[1];
  };
  return {
    cc: `cc-${read('src/parser/fingerprint.ts', 'PINNED_CC_VERSION')}`,
    opencode: `opencode-${read('src/opencode/fingerprint.ts', 'PINNED_OPENCODE_VERSION')}`,
    codex: `codex-${read('src/codex/fingerprint.ts', 'PINNED_CODEX_VERSION')}`,
  };
}

/** The census's classes, re-derived here so the two agree by construction. */
const CLASS_BY_NAME = new Map(
  Object.entries({
    Read: 'read', Write: 'write', Edit: 'edit', NotebookEdit: 'edit',
    Glob: 'search', Grep: 'search', Bash: 'shell', Agent: 'spawn',
    read: 'read', write: 'write', edit: 'edit', patch: 'edit',
    glob: 'search', grep: 'search', bash: 'shell', task: 'spawn',
    exec: 'shell', exec_command: 'shell', local_shell_call: 'shell',
    spawn_agent: 'spawn', wait_agent: 'spawn', send_message: 'spawn',
    send_input: 'spawn', list_agents: 'spawn',
  }),
);
const FILE_CLASSES = new Set(['read', 'write', 'edit']);
const FILE_KEY = new Map(
  Object.entries({ Read: 'file_path', Write: 'file_path', Edit: 'file_path', NotebookEdit: 'notebook_path', read: 'filePath', write: 'filePath', edit: 'filePath', patch: 'filePath' }),
);

const classOf = (name) => CLASS_BY_NAME.get(name) ?? 'other';
function filePathOf(name, input) {
  if (!FILE_CLASSES.has(classOf(name))) return undefined;
  const key = FILE_KEY.get(name);
  if (key === undefined || input === null || typeof input !== 'object') return undefined;
  const v = input[key];
  return typeof v === 'string' && v !== '' ? v : undefined;
}

const num = (v) => (typeof v === 'number' && Number.isFinite(v) ? v : 0);

// ---------------------------------------------------------------------------
// Engine readers -> the normalised shape the facts are computed from
//
//   session = { corpus, engine, sessionId, schemaOk, parked[], model?,
//               windowTokens?, costUsd?, costSource?, compactions[],
//               agents: [{ agentId, kind, tools[], usageSeries[] }] }
//   tool    = { ordinal, toolName, toolClass, filePath?, inputHash,
//               status: 'done'|'error'|'running'|'unknown', durationMs? }
//   turn    = { ordinal, input, cacheCreation, cacheRead, output }
// ---------------------------------------------------------------------------

function readCcCorpus(dir, corpus) {
  const sessions = [];
  const projects = join(dir, 'projects');
  if (!existsSync(projects)) return sessions;
  for (const slug of readdirSync(projects)) {
    const slugDir = join(projects, slug);
    if (!statSync(slugDir).isDirectory()) continue;
    for (const entry of readdirSync(slugDir)) {
      if (!entry.endsWith('.jsonl')) continue;
      const sessionId = entry.slice(0, -6);
      const files = [{ agentId: 'root', kind: 'main', path: join(slugDir, entry) }];
      const subDir = join(slugDir, sessionId, 'subagents');
      if (existsSync(subDir)) {
        for (const f of readdirSync(subDir)) {
          if (f.endsWith('.jsonl')) files.push({ agentId: f.slice('agent-'.length, -6), kind: 'subagent', path: join(subDir, f) });
        }
      }
      sessions.push(readCcSession(corpus, sessionId, files));
    }
  }
  return sessions;
}

function readCcSession(corpus, sessionId, files) {
  const agents = [];
  const compactions = [];
  let model;
  let malformed = 0;

  for (const f of files) {
    const tools = [];
    const usageById = new Map();
    const errorByToolUseId = new Map();
    let ordinal = 0;

    for (const line of readFileSync(f.path, 'utf8').split('\n')) {
      if (line.trim() === '') continue;
      let o;
      try {
        o = JSON.parse(line);
      } catch {
        malformed += 1;
        continue;
      }
      if (f.kind === 'main' && o.compactMetadata && typeof o.compactMetadata === 'object') {
        compactions.push({
          ordinal: tools.length,
          trigger: typeof o.compactMetadata.trigger === 'string' ? o.compactMetadata.trigger : 'unknown',
          promptBefore: num(o.compactMetadata.preTokens) || undefined,
          promptAfter: num(o.compactMetadata.postTokens) || undefined,
        });
      }
      const msg = o.message;
      if (!msg || typeof msg !== 'object') continue;
      if (typeof msg.model === 'string' && model === undefined) model = msg.model;

      // Usage, de-duplicated by message id: CC repeats the SAME usage object on
      // every content-block line of one streamed message, growing as it goes.
      // Keep the maximum per id and sum across distinct ids — the production
      // rule in `src/model/graft.ts`, restated rather than imported.
      if (typeof msg.id === 'string' && msg.usage && typeof msg.usage === 'object') {
        const u = msg.usage;
        const turn = {
          input: num(u.input_tokens),
          cacheCreation: num(u.cache_creation_input_tokens),
          cacheRead: num(u.cache_read_input_tokens),
          output: num(u.output_tokens),
        };
        const prev = usageById.get(msg.id);
        usageById.set(msg.id, prev === undefined ? { ...turn, ordinal: usageById.size } : {
          ordinal: prev.ordinal,
          input: Math.max(prev.input, turn.input),
          cacheCreation: Math.max(prev.cacheCreation, turn.cacheCreation),
          cacheRead: Math.max(prev.cacheRead, turn.cacheRead),
          output: Math.max(prev.output, turn.output),
        });
      }

      const content = msg.content;
      if (!Array.isArray(content)) continue;
      for (const b of content) {
        if (!b || typeof b !== 'object') continue;
        if (b.type === 'tool_use' && typeof b.name === 'string') {
          tools.push({
            id: typeof b.id === 'string' ? b.id : `#${String(ordinal)}`,
            ordinal: ordinal++,
            toolName: b.name,
            toolClass: classOf(b.name),
            filePath: filePathOf(b.name, b.input),
            inputHash: inputHash(b.input ?? null),
            status: 'done',
          });
        } else if (b.type === 'tool_result' && typeof b.tool_use_id === 'string') {
          errorByToolUseId.set(b.tool_use_id, b.is_error === true);
        }
      }
    }
    for (const t of tools) {
      const e = errorByToolUseId.get(t.id);
      t.status = e === true ? 'error' : e === false ? 'done' : 'unknown';
    }
    agents.push({
      agentId: f.agentId,
      kind: f.kind,
      tools,
      usageSeries: [...usageById.values()].sort((a, b) => a.ordinal - b.ordinal),
    });
  }

  return { corpus, engine: 'cc', sessionId, schemaOk: true, parked: [], model, compactions, agents, malformed };
}

function readOpenCodeCorpus(dir, corpus) {
  const db = new DatabaseSync(join(dir, 'opencode.db'), { readOnly: true });
  const sessions = [];
  try {
    const rows = db.prepare('SELECT id, parent_id, model, cost, time_created FROM session').all();
    const parts = db.prepare('SELECT id, session_id, message_id, data FROM part ORDER BY id').all();
    const bySession = new Map();
    for (const p of parts) {
      if (!bySession.has(p.session_id)) bySession.set(p.session_id, []);
      bySession.get(p.session_id).push(p);
    }
    // One SessionState per ROOT session; children become subagents.
    const children = new Map();
    for (const r of rows) {
      if (r.parent_id) {
        if (!children.has(r.parent_id)) children.set(r.parent_id, []);
        children.get(r.parent_id).push(r);
      }
    }
    for (const root of rows.filter((r) => !r.parent_id)) {
      const agents = [];
      const compactions = [];
      let cost = num(root.cost);
      const build = (row, kind) => {
        const tools = [];
        const usageSeries = [];
        let ordinal = 0;
        for (const p of bySession.get(row.id) ?? []) {
          let d;
          try {
            d = JSON.parse(p.data);
          } catch {
            continue;
          }
          if (d.type === 'tool' && typeof d.tool === 'string') {
            const st = d?.state?.status;
            const time = d?.state?.time;
            tools.push({
              id: typeof d.callID === 'string' ? d.callID : p.id,
              ordinal: ordinal++,
              toolName: d.tool,
              toolClass: classOf(d.tool),
              filePath: filePathOf(d.tool, d?.state?.input),
              inputHash: inputHash(d?.state?.input ?? null),
              status: st === 'error' ? 'error' : st === 'completed' ? 'done' : st === 'running' ? 'running' : 'unknown',
              durationMs: time && num(time.end) > 0 && num(time.start) > 0 ? num(time.end) - num(time.start) : undefined,
            });
          } else if (d.type === 'step-finish') {
            const t = d.tokens ?? {};
            usageSeries.push({
              ordinal: usageSeries.length,
              input: num(t.input),
              cacheCreation: num(t?.cache?.write),
              cacheRead: num(t?.cache?.read),
              output: num(t.output),
            });
            cost += num(d.cost);
          } else if (d.type === 'compaction') {
            compactions.push({ ordinal: tools.length, trigger: 'engine', promptBefore: undefined, promptAfter: undefined });
          }
        }
        agents.push({ agentId: row.id, kind, tools, usageSeries });
      };
      build(root, 'main');
      for (const c of children.get(root.id) ?? []) build(c, 'subagent');
      sessions.push({
        corpus, engine: 'opencode', sessionId: root.id, schemaOk: true, parked: [],
        model: typeof root.model === 'string' ? root.model : undefined,
        costUsd: num(root.cost) > 0 ? num(root.cost) : undefined,
        costSource: num(root.cost) > 0 ? 'engine' : undefined,
        compactions, agents, malformed: 0,
      });
    }
  } finally {
    db.close();
  }
  return sessions;
}

function readCodexCorpus(dir, corpus) {
  // One rollout file per THREAD. A thread's own file is its agent; the root is
  // the thread with no parent. Grouping is by directory (one run per capture).
  const byRun = new Map();
  for (const p of walk(dir).filter((f) => f.endsWith('.jsonl') && !f.includes('hook-stream'))) {
    const run = p.split(/[\\/]/).slice(0, 3).join('/');
    if (!byRun.has(run)) byRun.set(run, []);
    byRun.get(run).push(p);
  }
  const sessions = [];
  for (const [run, files] of byRun) {
    const agents = [];
    let windowTokens;
    let model;
    let sessionId = run;
    for (const p of files) {
      const tools = [];
      const usageSeries = [];
      let ordinal = 0;
      let threadId;
      let kind = 'subagent';
      for (const line of readFileSync(p, 'utf8').split('\n')) {
        if (line.trim() === '') continue;
        let o;
        try {
          o = JSON.parse(line);
        } catch {
          continue;
        }
        const pl = o.payload;
        if (!pl || typeof pl !== 'object') continue;
        if (o.type === 'session_meta' || pl.type === 'session_meta' || pl.id !== undefined && pl.cwd !== undefined) {
          if (typeof pl.id === 'string' && threadId === undefined) threadId = pl.id;
          const src = pl.source;
          if (src === undefined || src === null) kind = 'main';
        }
        if (pl.type === 'task_started') {
          const w = num(pl.model_context_window);
          if (w > 0) windowTokens = w;
        }
        if (pl.type === 'turn_context' && typeof pl.model === 'string' && model === undefined) model = pl.model;
        if (pl.model !== undefined && typeof pl.model === 'string' && model === undefined) model = pl.model;
        if (pl.type === 'token_count' && pl.info && typeof pl.info === 'object') {
          const last = pl.info.last_token_usage;
          const w = num(pl.info.model_context_window);
          if (w > 0) windowTokens = w;
          if (last && typeof last === 'object') {
            usageSeries.push({
              ordinal: usageSeries.length,
              // `input_tokens` here is the TOTAL sent; `cached_input_tokens` is
              // the cached part of it. Reported separately so the reader is not
              // asked to trust an arithmetic we did not measure.
              input: num(last.input_tokens) - num(last.cached_input_tokens),
              cacheCreation: num(last.cache_write_input_tokens),
              cacheRead: num(last.cached_input_tokens),
              output: num(last.output_tokens),
            });
          }
        }
        const isCall = pl.type === 'function_call' || pl.type === 'custom_tool_call' || pl.type === 'local_shell_call';
        if (isCall) {
          const name = typeof pl.name === 'string' ? pl.name : 'local_shell_call';
          let input = null;
          if (pl.type === 'function_call') {
            try {
              input = JSON.parse(pl.arguments ?? '{}');
            } catch {
              input = String(pl.arguments ?? '');
            }
          } else if (pl.type === 'custom_tool_call') input = typeof pl.input === 'string' ? pl.input : (pl.input ?? null);
          else input = pl.action ?? null;
          tools.push({
            id: typeof pl.call_id === 'string' ? pl.call_id : `#${String(ordinal)}`,
            ordinal: ordinal++,
            toolName: name,
            toolClass: classOf(name),
            filePath: filePathOf(name, input),
            inputHash: inputHash(input),
            // No structural error signal exists. `unknown`, never `done`: a
            // default of `done` would report a zero error count as a fact.
            status: 'unknown',
          });
        }
      }
      agents.push({ agentId: threadId ?? p, kind, tools, usageSeries });
    }
    if (agents.length > 0 && !agents.some((a) => a.kind === 'main')) agents[0].kind = 'main';
    sessions.push({ corpus, engine: 'codex', sessionId, schemaOk: true, parked: [], model, windowTokens, compactions: [], agents, malformed: 0 });
  }
  return sessions;
}

// ---------------------------------------------------------------------------
// Facts
// ---------------------------------------------------------------------------

function deriveFacts(session, loopMin, spikeTokens) {
  const allTools = session.agents.flatMap((a) => a.tools);
  const statusKnown = allTools.some((t) => t.status === 'done' || t.status === 'error');

  // F1 — per-file counts and first/last touch ordinal.
  const files = new Map();
  for (const a of session.agents) {
    for (const t of a.tools) {
      if (t.filePath === undefined) continue;
      let f = files.get(t.filePath);
      if (f === undefined) {
        f = { path: t.filePath, read: 0, edit: 0, write: 0, error: 0, first: t.ordinal, last: t.ordinal };
        files.set(t.filePath, f);
      }
      if (t.toolClass === 'read') f.read += 1;
      else if (t.toolClass === 'edit') f.edit += 1;
      else if (t.toolClass === 'write') f.write += 1;
      if (t.status === 'error') f.error += 1;
      f.first = Math.min(f.first, t.ordinal);
      f.last = Math.max(f.last, t.ordinal);
    }
  }

  // F2 — per tool.
  const tools = new Map();
  for (const t of allTools) {
    let e = tools.get(t.toolName);
    if (e === undefined) {
      e = { toolName: t.toolName, calls: 0, errors: 0, durationSum: 0, durationMax: 0 };
      tools.set(t.toolName, e);
    }
    e.calls += 1;
    if (t.status === 'error') e.errors += 1;
    if (t.durationMs !== undefined) {
      e.durationSum += t.durationMs;
      e.durationMax = Math.max(e.durationMax, t.durationMs);
    }
  }

  // F3 — identical-call loops, WITHIN ONE AGENT (locked answer).
  const loops = [];
  for (const a of session.agents) {
    const seen = new Map();
    for (const t of a.tools) {
      const k = `${t.toolName}�${t.inputHash}`;
      if (!seen.has(k)) seen.set(k, []);
      seen.get(k).push(t.ordinal);
    }
    for (const [k, ordinals] of seen) {
      if (ordinals.length >= loopMin) {
        loops.push({ agentId: a.agentId, toolName: k.split('�')[0], count: ordinals.length, ordinals, readClass: classOf(k.split('�')[0]) === 'read' });
      }
    }
  }

  // F4 — churn chain: Edit/Write(X) -> any error tool -> Edit/Write(X), same agent.
  const churn = [];
  for (const a of session.agents) {
    const writes = a.tools.filter((t) => (t.toolClass === 'edit' || t.toolClass === 'write') && t.filePath !== undefined);
    for (let i = 0; i < writes.length; i += 1) {
      for (let j = i + 1; j < writes.length; j += 1) {
        if (writes[i].filePath !== writes[j].filePath) continue;
        const between = a.tools.filter((t) => t.ordinal > writes[i].ordinal && t.ordinal < writes[j].ordinal);
        if (between.some((t) => t.status === 'error')) {
          churn.push({ agentId: a.agentId, path: writes[i].filePath, from: writes[i].ordinal, to: writes[j].ordinal, ordinals: between.map((t) => t.ordinal) });
        }
        break; // the NEXT write of the same file only
      }
    }
  }

  // F5 — burn.
  const sumTurns = (turns) => turns.reduce(
    (acc, t) => ({ prompt: acc.prompt + t.input + t.cacheCreation + t.cacheRead, output: acc.output + t.output }),
    { prompt: 0, output: 0 },
  );
  const perAgentBurn = session.agents.map((a) => ({ agentId: a.agentId, ...sumTurns(a.usageSeries) }));
  const burn = perAgentBurn.reduce((acc, b) => ({ prompt: acc.prompt + b.prompt, output: acc.output + b.output }), { prompt: 0, output: 0 });
  const hasSeries = session.agents.some((a) => a.usageSeries.length > 0);

  // F6 — cache ratio per agent.
  const cacheRatios = session.agents
    .filter((a) => a.usageSeries.length > 0)
    .map((a) => {
      const s = sumTurns(a.usageSeries);
      const cacheRead = a.usageSeries.reduce((n, t) => n + t.cacheRead, 0);
      return { agentId: a.agentId, ratio: s.prompt > 0 ? cacheRead / s.prompt : null };
    })
    .filter((r) => r.ratio !== null);

  // F7 — context churn: turn-over-turn delta of cache-creation tokens.
  const contextChurn = [];
  const deltas = [];
  for (const a of session.agents) {
    for (let i = 1; i < a.usageSeries.length; i += 1) {
      const d = a.usageSeries[i].cacheCreation - a.usageSeries[i - 1].cacheCreation;
      deltas.push(d);
      if (d >= spikeTokens) contextChurn.push({ agentId: a.agentId, ordinal: a.usageSeries[i].ordinal, delta: d });
    }
  }

  // F8 — subagents.
  const subagents = session.agents.filter((a) => a.kind === 'subagent');
  const silent = subagents.filter((a) => a.tools.length === 0);
  const spawnCalls = allTools.filter((t) => t.toolClass === 'spawn');
  const spawnNotDone = spawnCalls.filter((t) => t.status !== 'done');

  // F10 — context fill.
  const lastTurn = session.agents.find((a) => a.kind === 'main')?.usageSeries.at(-1);
  const contextNowPrompt = lastTurn ? lastTurn.input + lastTurn.cacheCreation + lastTurn.cacheRead : undefined;
  const contextFill = session.windowTokens && contextNowPrompt !== undefined && session.windowTokens > 0
    ? contextNowPrompt / session.windowTokens
    : undefined;

  return {
    corpus: session.corpus, engine: session.engine, sessionId: session.sessionId,
    F1: { files: files.size, rows: [...files.values()], available: files.size > 0, errorColumnAvailable: statusKnown },
    F2: { tools: tools.size, rows: [...tools.values()], errorColumnAvailable: statusKnown, durationAvailable: allTools.some((t) => t.durationMs !== undefined) },
    F3: { loops: loops.length, rows: loops },
    F4: { chains: churn.length, rows: churn, available: statusKnown },
    F5: { burn, perAgent: perAgentBurn, available: hasSeries },
    F6: { ratios: cacheRatios, available: cacheRatios.length > 0 },
    F7: { spikes: contextChurn.length, deltas, available: deltas.length > 0 },
    F8: { subagents: subagents.length, silent: silent.length, spawnCalls: spawnCalls.length, spawnNotDone: spawnNotDone.length, available: true },
    F9: { costUsd: session.costUsd, costSource: session.costSource, available: session.costUsd !== undefined },
    F10: { windowTokens: session.windowTokens, contextFill, available: contextFill !== undefined },
    F11: { coverage: session.schemaOk && session.parked.length === 0 ? 'full' : 'excluded:parked', available: true },
    F12: { count: session.compactions.length, rows: session.compactions, available: session.compactions.length > 0 },
    _toolCount: allTools.length,
    _statusKnown: statusKnown,
  };
}

// ---------------------------------------------------------------------------

function main() {
  const anchors = readAnchors();
  const anchorSet = new Set(Object.values(anchors));
  const sessions = [];

  for (const name of readdirSync(FIXTURES).sort()) {
    const dir = join(FIXTURES, name);
    if (!statSync(dir).isDirectory()) continue;
    if (existsSync(join(dir, 'opencode.db'))) sessions.push(...readOpenCodeCorpus(dir, name));
    else if (existsSync(join(dir, 'projects'))) sessions.push(...readCcCorpus(dir, name));
    else {
      const jsonl = walk(dir).filter((p) => p.endsWith('.jsonl') && !p.includes('hook-stream'));
      const isCodex = jsonl.slice(0, 4).some((p) => (readFileSync(p, 'utf8').split('\n', 1)[0] ?? '').includes('"payload"'));
      if (isCodex) sessions.push(...readCodexCorpus(dir, name));
    }
  }

  // ---- 0.6: the two constants, from the ANCHOR corpora's histograms --------
  const anchorSessions = sessions.filter((s) => anchorSet.has(s.corpus));

  // LOOP_MIN: how many loops each candidate threshold selects.
  const repeatCounts = [];
  for (const s of anchorSessions) {
    for (const a of s.agents) {
      const seen = new Map();
      for (const t of a.tools) {
        const k = `${t.toolName}�${t.inputHash}`;
        seen.set(k, (seen.get(k) ?? 0) + 1);
      }
      for (const n of seen.values()) repeatCounts.push(n);
    }
  }
  const loopHistogram = {};
  for (const n of repeatCounts) loopHistogram[n] = (loopHistogram[n] ?? 0) + 1;
  const loopsAtThreshold = {};
  for (const th of [2, 3, 4, 5, 6]) loopsAtThreshold[th] = repeatCounts.filter((n) => n >= th).length;

  // SPIKE_TOKENS: the value at which <= 5% of real turns qualify, to the
  // nearest thousand. Both candidate quantities are reported — the per-turn
  // cache-creation figure and its turn-over-turn delta — because the spec
  // sentence names the delta and a reader who assumed the level would get a
  // different constant. The one used is named beside the number.
  const allDeltas = [];
  const allLevels = [];
  for (const s of anchorSessions) {
    for (const a of s.agents) {
      for (let i = 0; i < a.usageSeries.length; i += 1) {
        allLevels.push(a.usageSeries[i].cacheCreation);
        if (i > 0) allDeltas.push(a.usageSeries[i].cacheCreation - a.usageSeries[i - 1].cacheCreation);
      }
    }
  }
  const pick95 = (values) => {
    if (values.length === 0) return null;
    const sorted = [...values].sort((a, b) => a - b);
    const idx = Math.floor(sorted.length * 0.95);
    const raw = sorted[Math.min(idx, sorted.length - 1)];
    return { raw, rounded: Math.max(1000, Math.round(raw / 1000) * 1000), n: values.length };
  };
  const spikeFromDelta = pick95(allDeltas);
  const spikeFromLevel = pick95(allLevels);
  const SPIKE_TOKENS = spikeFromDelta?.rounded ?? 1000;
  const qualifying = allDeltas.filter((d) => d >= SPIKE_TOKENS).length;

  // ---- facts, now that the constants exist -------------------------------
  const facts = sessions.map((s) => deriveFacts(s, LOOP_MIN_DEFAULT, SPIKE_TOKENS));

  // ---- the fact x engine verdict table ------------------------------------
  const ENGINES = ['cc', 'opencode', 'codex'];
  const FACT_IDS = ['F1', 'F2', 'F3', 'F4', 'F5', 'F6', 'F7', 'F8', 'F9', 'F10', 'F11', 'F12'];
  const table = {};
  for (const id of FACT_IDS) {
    table[id] = {};
    for (const eng of ENGINES) {
      const rows = facts.filter((f) => f.engine === eng);
      const fired = rows.filter((f) => f[id].available === true).length;
      table[id][eng] = { sessions: rows.length, fired };
    }
  }

  const report = {
    generatedFrom: 'lab/spike/stats/derive-facts.mjs',
    anchors,
    constants: { LOOP_MIN: LOOP_MIN_DEFAULT, SPIKE_TOKENS, spikeFromDelta, spikeFromLevel, qualifyingTurns: qualifying, totalDeltas: allDeltas.length },
    loopHistogram, loopsAtThreshold,
    sessions: facts.length,
    table,
    facts,
  };

  mkdirSync(OUT_DIR, { recursive: true });
  writeFileSync(join(OUT_DIR, 'facts.json'), `${JSON.stringify(report, null, 1)}\n`, 'utf8');

  console.log(`sessions derived: ${facts.length}  (anchor sessions: ${anchorSessions.length})`);
  console.log(`SPIKE_TOKENS = ${String(SPIKE_TOKENS)}  from the 95th percentile of ${String(allDeltas.length)} turn-over-turn cache-creation deltas (raw ${String(spikeFromDelta?.raw)}); ${String(qualifying)}/${String(allDeltas.length)} turns qualify = ${(100 * qualifying / Math.max(1, allDeltas.length)).toFixed(1)}%`);
  console.log(`LOOP_MIN = ${String(LOOP_MIN_DEFAULT)}; loops selected at thresholds ${JSON.stringify(loopsAtThreshold)}`);
  console.log('');
  console.log('fact   cc              opencode        codex');
  for (const id of FACT_IDS) {
    const cell = (e) => `${String(table[id][e].fired)}/${String(table[id][e].sessions)}`.padEnd(16);
    console.log(`${id.padEnd(6)} ${cell('cc')}${cell('opencode')}${cell('codex')}`);
  }
}

main();

