input.new_string:
// CORPUS DISCOVERY IS STRUCTURAL, AND IT HAS TO BE PRECISE IN BOTH
// DIRECTIONS. A first draft classified any directory holding a `.jsonl`
// whose first line contains `"payload"` as a Codex corpus, which swept in
// `fixtures/synthetic-codex-structure/` — 37 hand-made single-line MUTATION
// fixtures, each of which then reported as a "session" with no usage. They
// are inputs a fingerprint must REFUSE, not recordings of anything, and
// counting them made every Codex column read 5/42 instead of 5/5.
//
//   OpenCode -> an `opencode.db` ANYWHERE beneath the corpus. Not at its
//               root: `opencode-1.18.25` keeps its store one level down, in
//               `moved-project/`, and a root-only test silently skipped it.
//   Codex    -> a rollout under a `sessions/` directory, which is the real
//               capture layout and which no synthetic fixture has (14 of 14
//               real files, 0 of 37 synthetic).
//   CC       -> a `projects/` directory.
const skipped = [];
for (const name of readdirSync(FIXTURES).sort()) {
  const dir = join(FIXTURES, name);
  if (!statSync(dir).isDirectory()) continue;
  const files = walk(dir);
  const dbs = files.filter((p) => p.endsWith('opencode.db'));
  const rollouts = files.filter((p) => p.endsWith('.jsonl') && p.replace(/\\/g, '/').includes('/sessions/'));
  if (dbs.length > 0) for (const db of dbs) sessions.push(...readOpenCodeCorpus(db, name));
  else if (existsSync(join(dir, 'projects'))) sessions.push(...readCcCorpus(dir, name));
  else if (rollouts.length > 0) sessions.push(...readCodexCorpus(dir, name, rollouts));
  else skipped.push(name);
}
// Rule 18: a scan that skips an input says so, with the reason.
console.log(`corpora skipped as not session corpora (${String(skipped.length)}): ${skipped.join(', ')}`);

