// Remove the NUL bytes that reached both spike scripts as map-key separators.
//
// They ran correctly — a NUL is a legal JavaScript string character and
// `split` on it works — so nothing failed. What they did was make the files
// BINARY to git: no reviewable diff, and `git grep`/`grep` abandon the stream,
// which is the recorded hazard that already costs this repository a documented
// trap. One of them was committed before it was noticed.
//
// The fix is not a different separator. It is to stop having one: a structural
// JSON key cannot be ambiguous and cannot contain a control byte, and the
// toolName is read back with JSON.parse instead of by splitting on a character
// nobody can see.
import { readFileSync, writeFileSync } from 'node:fs';

const NUL = String.fromCharCode(0);

/** Slice-based; `.replace` honours `$'` and has duplicated whole files here. */
function replaceAll(text, needle, replacement) {
  let out = '';
  let i = 0;
  for (;;) {
    const j = text.indexOf(needle, i);
    if (j < 0) return out + text.slice(i);
    out += text.slice(i, j) + replacement;
    i = j + needle.length;
  }
}

const EDITS = [
  [
    'lab/spike/stats/toolclass-census.mjs',
    [[`\`\${engine}${NUL}\${toolName}\``, 'JSON.stringify([engine, toolName])']],
  ],
  [
    'lab/spike/stats/derive-facts.mjs',
    [
      [`\`\${t.toolName}${NUL}\${t.inputHash}\``, 'JSON.stringify([t.toolName, t.inputHash])'],
      [`k.split('${NUL}')[0]`, 'JSON.parse(k)[0]'],
    ],
  ],
];

for (const [file, pairs] of EDITS) {
  let text = readFileSync(file, 'utf8');
  const before = text;
  for (const [needle, replacement] of pairs) {
    const n = text.split(needle).length - 1;
    console.log(`${file}: ${String(n)} x ${JSON.stringify(needle)}`);
    text = replaceAll(text, needle, replacement);
  }
  if (text !== before) writeFileSync(file, text, 'utf8');
  const buf = readFileSync(file);
  let control = 0;
  for (let i = 0; i < buf.length; i += 1) {
    const c = buf[i];
    if (c < 0x09 || (c > 0x0d && c < 0x20)) control += 1;
  }
  console.log(`${file}: control bytes now ${String(control)}`);
  if (control !== 0) throw new Error(`${file} still has control bytes`);
}
console.log('OK');

