/**
 * Phase 0, DoD 0.7 — how big is a `StatsRecord` on disk, and what does that
 * make the retention default cost?
 *
 * THROWAWAY SPIKE CODE. Reads `facts.json`, which `derive-facts.mjs` wrote, so
 * the two cannot disagree about what a session contains.
 *
 * WHAT THIS DOES NOT DECIDE. The store format is JSON Lines by DECISION, not by
 * measurement — the locked answer to Phase 0's third open question, with no
 * SQLite branch. Nothing here argues for a format. The only thing the size
 * measurement is allowed to move is the RETENTION DEFAULT, and the projection
 * below is the whole reason it is taken.
 *
 * Usage: node lab/spike/stats/record-size.mjs
 */
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';

const OUT_DIR = 'docs/evidence/phase-0-stats';
const report = JSON.parse(readFileSync(join(OUT_DIR, 'facts.json'), 'utf8'));

/**
 * A draft `StatsRecord` in the spec's §F shape, built from the derived facts.
 *
 * It is a DRAFT: Phase 2 owns the real schema. What it has to get right for a
 * size measurement is the SHAPE — which lists exist and roughly how long they
 * are — because that is what the bytes are. Every list here is the real derived
 * one, not a placeholder, so the number is a measurement of this corpus rather
 * than of an invented record.
 */
function draftRecord(f) {
  return {
    statsSchemaVersion: 1,
    sessionId: f.sessionId,
    engine: f.engine,
    projectSlug: f.corpus,
    startedAt: 1_756_000_000_000,
    endedAt: 1_756_000_600_000,
    derivedAt: 1_756_000_600_000,
    coverage: f.F11.coverage,
    agents: f.F5.perAgent.map((a) => ({
      agentId: a.agentId,
      prompt: a.prompt,
      output: a.output,
      cacheRatio: f.F6.ratios.find((r) => r.agentId === a.agentId)?.ratio ?? null,
      tools: 0,
    })),
    files: f.F1.rows.map((r) => ({
      path: r.path, read: r.read, edit: r.edit, write: r.write, error: r.error,
      firstTouch: r.first, lastTouch: r.last,
    })),
    tools: f.F2.rows.map((r) => ({
      toolName: r.toolName, calls: r.calls, errors: r.errors,
      durationSumMs: r.durationSum, durationMaxMs: r.durationMax,
    })),
