// Make fixtures/cc-2.1.260 internally consistent about its own repository root.
//
// THE DEFECT. The corpus claims FOUR distinct `cwd` roots. Three are the
// intended scrubbed form (`C:\Users\dev\projects\agent-deck`, and two paths
// below it); the fourth, on 123 lines, is `<HOME>\Documents\projects\agent-deck`
// — the SAME directory, spelled a fourth way. Every other captured CC corpus
// has exactly one distinct `cwd`.
//
// HOW IT GOT THERE. The harvest rewrote the repo path first, then two redactors
// ran. Occurrences the first rewrite did not reach (a different escaping depth)
// were caught piecemeal by the later two: the identity redactor mapped the
// home-folder name, and the path redactor replaced the drive-and-user prefix
// with `<HOME>`. Each step was correct on its own and the composition was not.
//
// WHY IT MATTERS even though it is privacy-SAFE (this is over-redaction, never
// under-): `projectSlug` is derived from the slug directory and correlated
// against `cwd`. 123 lines of this corpus would correlate against nothing, and
// a future test that joins the two would report a defect that is really a
// fixture artefact. `<HOME>` in a `cwd` is an established form here
// (synthetic-dropped-actions uses it) — what is not established is ONE corpus
// using two spellings of ONE root.
//
// The fix is textual and narrow: the fourth spelling becomes the first.
import { readFileSync, writeFileSync, readdirSync, statSync } from 'node:fs';
import { join } from 'node:path';

const ROOT = 'fixtures/cc-2.1.260';
const BS = String.fromCharCode(92); // a single backslash, never typed literally

// Escaped (as it appears inside a .jsonl) and plain (as it appears in prose).
const FROM_ESC = `<HOME>${BS}${BS}Documents${BS}${BS}projects${BS}${BS}agent-deck`;
const TO_ESC = `C:${BS}${BS}Users${BS}${BS}dev${BS}${BS}projects${BS}${BS}agent-deck`;
const FROM_PLAIN = `<HOME>${BS}Documents${BS}projects${BS}agent-deck`;
const TO_PLAIN = `C:${BS}Users${BS}dev${BS}projects${BS}agent-deck`;

const walk = (d) =>
  readdirSync(d, { withFileTypes: true }).flatMap((e) =>
    e.isDirectory() ? walk(join(d, e.name)) : [join(d, e.name)],
  );

/** Slice-based; `.replace` honours `$'` and has duplicated whole files here. */
function replaceAll(text, needle, replacement) {
  let out = '';
  let i = 0;
  for (;;) {
    const j = text.indexOf(needle, i);
    if (j < 0) return out + text.slice(i);
    out += text.slice(i, j) + replacement;
    i = j + needle.length;
  }
}

let esc = 0;
let plain = 0;
for (const file of walk(ROOT)) {
  const before = readFileSync(file, 'utf8');
  let text = before;
  esc += text.split(FROM_ESC).length - 1;
  text = replaceAll(text, FROM_ESC, TO_ESC);
  plain += text.split(FROM_PLAIN).length - 1;
  text = replaceAll(text, FROM_PLAIN, TO_PLAIN);
  if (text !== before) writeFileSync(file, text, 'utf8');
}

// ---- proofs --------------------------------------------------------------
const cwds = new Map();
let homeLeft = 0;
for (const file of walk(ROOT)) {
  const s = readFileSync(file, 'utf8');
  homeLeft += s.split('<HOME>').length - 1;
  if (!file.endsWith('.jsonl')) continue;
  for (const line of s.split('\n')) {
    if (line.trim() === '') continue;
    let o;
    try {
      o = JSON.parse(line);
    } catch {
      continue;
    }
    if (typeof o.cwd === 'string') cwds.set(o.cwd, (cwds.get(o.cwd) ?? 0) + 1);
  }
}
console.log(JSON.stringify({ escapedRewrites: esc, plainRewrites: plain, homePlaceholdersLeft: homeLeft }, null, 1));
console.log('distinct cwd values now:');
for (const [k, v] of [...cwds].sort((a, b) => b[1] - a[1])) console.log(`  ${String(v).padStart(4)}  ${JSON.stringify(k)}`);

