function classifyCorpus(dir) {
  const files = walk(dir);
  // ANYWHERE beneath the corpus, not at its root. `opencode-1.18.25` keeps its
  // store in `moved-project/`, and a root-only `existsSync` skipped that corpus
  // silently — the fail-open shape rule 18 exists for. It was harmless here
  // only by luck (that store holds zero `part` rows), and luck is not a check.
  const db = files.find((p) => p.endsWith('opencode.db'));
  if (db !== undefined) return { engine: 'opencode', dbs: files.filter((p) => p.endsWith('opencode.db')) };
  if (existsSync(join(dir, 'projects'))) return { engine: 'cc' };
  const jsonl = files.filter((p) => p.endsWith('.jsonl') && !p.includes('hook-stream'));
  for (const p of jsonl.slice(0, 4)) {
    const head = readFileSync(p, 'utf8').split('\n', 1)[0] ?? '';
    if (head.includes('"payload"')) return { engine: 'codex' };
  }
  return null;
}

