1	/**
2	 * Phase 0, DoD 0.3 — tool-class census across every committed corpus.
3	 *
4	 * THROWAWAY SPIKE CODE. It is frozen at the phase close and never imported by
5	 * `src/`. It imports only `node:` builtins, deliberately: the census is
6	 * evidence about the corpora, and evidence produced by the code under test is
7	 * not evidence. `scripts/opencode-golden.mjs` is the precedent.
8	 *
9	 * WHAT IT ANSWERS. For every distinct tool name in every corpus: which engine
10	 * wrote it, how many times it was called, whether the call carries a
11	 * STRUCTURED input object at all, and which key of that object holds a
12	 * filesystem path. Phase 1 generates `src/stats/toolclass.ts` from this table
13	 * rather than from memory.
14	 *
15	 * WHY "structured" is its own column and not an implementation detail. Codex's
16	 * `exec` is a `custom_tool_call` whose `input` is a STRING of JavaScript, not
17	 * an object. A census that assumed every tool call has an input object would
18	 * report `exec` as "no file argument" and be right by accident, for the wrong
19	 * reason, and would break the moment a string-input tool did name a file. The
20	 * three states are distinct and all three are reported: no input, string
21	 * input, object input.
22	 *
23	 * Usage:
24	 *   node lab/spike/stats/toolclass-census.mjs            # writes the report
25	 *   node lab/spike/stats/toolclass-census.mjs --stdout   # prints instead
26	 */
27	import { readFileSync, readdirSync, existsSync, writeFileSync, mkdirSync, statSync } from 'node:fs';
28	import { join, basename } from 'node:path';
29	import { DatabaseSync } from 'node:sqlite';
30	
31	const FIXTURES = 'fixtures';
32	const OUT_DIR = 'docs/evidence/phase-0-stats';
33	
34	/**
35	 * The three provenance anchors, re-measured from the fingerprint modules
36	 * rather than written down here. A corpus name is not an anchor because it
