// Record the two substantive findings the verifier raised: the corpus's own
// fourth spelling of its root (now repaired) and the engine split behind
// SPIKE_TOKENS' <= 5%.
import { readFileSync, writeFileSync } from 'node:fs';

function insertBefore(text, anchor, block) {
  const i = text.indexOf(anchor);
  if (i < 0) throw new Error(`NOT FOUND: ${anchor.slice(0, 60)}`);
  if (text.indexOf(anchor, i + 1) >= 0) throw new Error(`NOT UNIQUE: ${anchor.slice(0, 60)}`);
  return text.slice(0, i) + block + text.slice(i);
}

// ---- 1. the corpus README: the fifth spelling, found and repaired ---------
const README = 'fixtures/cc-2.1.260/README.md';
const readmeBlock = `**A FIFTH SPELLING SURVIVED THE FIRST PASS AND WAS REPAIRED.** The composition of three correct
steps produced one incorrect result: occurrences the repo-path rewrite did not reach (a different
escaping depth) were caught piecemeal by the two redactors instead — the identity redactor mapped
the home-folder name, and the path redactor replaced the drive-and-user prefix — leaving
**371 occurrences of \`<HOME>\\Documents\\projects\\agent-deck\`, 123 of them as \`cwd\` values**. Same
directory, spelled a fourth way, in a corpus whose slug says otherwise.

It was **privacy-safe** — over-redaction, never under — and it was still wrong: \`projectSlug\` is
derived from the slug directory and correlated against \`cwd\`, so 123 lines would have correlated
against nothing, and a future test joining the two would have reported a defect that was really a
fixture artefact. Every other captured CC corpus carries exactly **one** distinct \`cwd\`.

Repaired by rewriting that spelling to the first. The corpus now carries **three** \`cwd\` values,
all consistent: the root (1,015), \`root\\lab\` (789) and \`root\\lab\\docs\` (3). The 358 remaining
\`<HOME>\` placeholders are OTHER directories and are correctly redacted — \`<HOME>\` in a \`cwd\` is an
established form here (\`synthetic-dropped-actions\` uses it); what was not established is one corpus
using two spellings of one root. Found by \`phase-verifier\`, 2026-09-05.

`;
let readme = readFileSync(README, 'utf8');
readme = insertBefore(readme, '**The slug needs its own step', readmeBlock);
writeFileSync(README, readme, 'utf8');

// ---- 2. VERDICT: the SPIKE_TOKENS engine split ---------------------------
const VERDICT = 'docs/evidence/phase-0-stats/VERDICT.md';
const verdictBlock = `**THE <= 5 % IS A MIXED-ENGINE STATISTIC, AND ON THE ONLY ENGINE THAT CAN PRODUCE F7 IT IS 6.0 %.**
Raised by \`phase-verifier\` after the scope was settled, and recorded here rather than acted on,
because the gate owner settled the scope and this evidence was not in view when they did.

Splitting the same 709 captured deltas by engine:

| engine | n | non-zero | p95 | at >= 4,000 | share |
|---|---:|---:|---:|---:|---:|
| cc | 484 | 228 | 4,543 | 29 | **6.0 %** |
| opencode | 181 | **0** | 0 | 0 | 0 % |
| codex | 44 | **0** | 0 | 0 | 0 % |

OpenCode's \`tokens.cache.write\` is **0 in all 210 \`step-finish\` rows** across all three stores, and
Codex's \`cache_write_input_tokens\` is never positive either. So **225 of the 709 denominator entries
can never qualify**, and they are what pulls the figure under the ceiling. On CC alone the smallest
whole thousand satisfying <= 5 % is **5,000** (22 of 484 = 4.5 %).

This is the F9 finding in a second costume — a field that is present and identically zero — and the
table above reads \`F7 opencode DERIVABLE 5/0\` and \`F7 codex DERIVABLE 5/0\` as "no spike in these
sessions" when the stronger statement is available: **neither engine writes a non-zero
cache-creation figure at all in any committed corpus**, so F7 cannot fire for them regardless of the
threshold. The verdict rows are not wrong; they are weaker than the evidence supports.

`;
let verdict = readFileSync(VERDICT, 'utf8');
verdict = insertBefore(verdict, '### `LOOP_MIN = 3`', verdictBlock);
writeFileSync(VERDICT, verdict, 'utf8');

for (const f of [README, VERDICT]) {
  const t = readFileSync(f, 'utf8');
  console.log(`${f}: CR=${String((t.match(/\r/g) ?? []).length)} LF=${String((t.match(/\n/g) ?? []).length)}`);
}
console.log('OK');

